import ctypes,os,pathlib,select,sys,time,json
p=pathlib.Path(sys.argv[1]);lib=ctypes.CDLL(None,use_errno=True)
fd=lib.inotify_init1(os.O_NONBLOCK|os.O_CLOEXEC)
if fd<0:raise OSError(ctypes.get_errno(),'inotify_init1')
if lib.inotify_add_watch(fd,os.fsencode(p),0x80|0x8)<0:raise OSError(ctypes.get_errno(),'inotify_add_watch')
deadline=time.monotonic()+600
while True:
 if any((p/n).exists() for n in ['GENERATION_COMPLETE.json','ERROR.json']):
  print('terminal');break
 remaining=deadline-time.monotonic()
 if remaining<=0:print('interval');break
 if select.select([fd],[],[],remaining)[0]:os.read(fd,65536)
os.close(fd)
